WITH category_node AS (
    SELECT id FROM sys_category WHERE app_code = 'youanshang' AND type = 'knowledge_point' AND code = 'kp_pf_b_relation'
)
INSERT INTO sys_content (app_code, title, slug, content_json, content_html, summary, category_id, tags, is_pinned, is_public, is_published, publish_time, view_count, sort_order, extra, created_by, created_time)
SELECT 'gongkao', '售价成本利润关系', 'kp-pf-b-relation', CAST($${"type": "doc", "content": [{"type": "heading", "attrs": {"level": 1}, "content": [{"type": "text", "text": "售价、成本与利润"}]}, {"type": "highlightBlock", "attrs": {"backgroundColor": "#fffbeb", "borderColor": "#f59e0b", "icon": "💡"}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "核心常识：", "marks": [{"type": "bold"}]}, {"type": "text", "text": "利润 = 售价 - 成本。这是经济学最底层的加减法。"}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "一、概念拆解"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "无论题目怎么花里胡哨（打折、提价、满减），这三个要素的绝对三角关系永远不会被打破。"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "二、易错点纠偏"}]}, {"type": "highlightBlock", "attrs": {"backgroundColor": "#fef2f2", "borderColor": "#ef4444", "icon": "⚠️"}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "利润与利润率混淆：", "marks": [{"type": "bold"}]}, {"type": "text", "text": "利润是一个绝对的“钱数”（单位是元）。利润率是一个相对的“比值”（带百分号）。千万不要把赚了 20 元和赚了 20% 搞混！"}]}]}]}$$ AS jsonb), NULL, '售价成本利润关系的核心考点与实战推导。', category_node.id, CAST('["数量关系", "经济利润", "售价成本利润关系"]' AS jsonb), FALSE, TRUE, TRUE, NOW(), 0, 0, CAST('{"content_type": "knowledge_point", "category_code": "kp_pf_b_relation", "source": "fba_content_engine"}' AS jsonb), 1, NOW()
FROM category_node ON CONFLICT (slug) DO UPDATE SET title = EXCLUDED.title, content_json = EXCLUDED.content_json, summary = EXCLUDED.summary, category_id = EXCLUDED.category_id, tags = EXCLUDED.tags, updated_time = NOW();
